// PM search terms for the Bundesagentur Jobsuche API (P2-03).
// 'Produktmanagerin' returns the same jobs as 'Produktmanager', so it is left out.
const terms = ['Product Manager', 'Produktmanager', 'Product Owner', 'Head of Product'];
return terms.map(was => ({ json: { was } }));

// One item per unique job (by referenznummer) across all search terms.
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  for (const job of item.json.ergebnisliste || []) {
    const ref = job.referenznummer;
    if (!ref || seen.has(ref)) continue;
    seen.add(ref);
    out.push({ json: { ...job, detailsKey: Buffer.from(ref).toString('base64') } });
  }
}
return out;

// Map each Bundesagentur job to JobPilot's common job shape.
const MAX_DESC = 6000; // characters sent on to scoring
const list = $('Flatten + de-duplicate').all();
return $input.all().map((item, i) => {
  const s = list[i].json;            // search result (always there)
  const d = item.json || {};         // details (may be an error)
  const loc = (s.stellenlokationen || []).map(l => l.adresse?.ort).filter(Boolean);
  const desc = (d.stellenangebotsBeschreibung || '').replace(/\*\*/g, '').replace(/\n{3,}/g, '\n\n').trim();
  const salary = s.gehaltsspanneVon ? `${s.gehaltsspanneVon}–${s.gehaltsspanneBis || ''} (${s.artDerVerguetung || ''})` : null;
  return { json: {
    id: `ba:${s.referenznummer}`,
    source: 'bundesagentur',
    market: 'DE',
    title: (s.stellenangebotsTitel || '').trim(),
    company: s.firma || null,
    location: [...new Set(loc)].join(', ') || null,
    remote: s.homeofficemoeglich ? (s.homeofficetyp || 'possible') : 'no',
    published: s.datumErsteVeroeffentlichung || null,
    salary,
    description: desc.slice(0, MAX_DESC),
    description_missing: !desc,
    link: `https://www.arbeitsagentur.de/jobsuche/jobdetail/${s.referenznummer}`,
    external_link: s.externeURL || null,
  } };
});

// PM title phrases for Adzuna, London (P2-04). Matched in the job title only.
// One page of 50 per phrase: the largest phrase returned 16 jobs a day. Add page 2 if a count nears 50.
const phrases = ['product manager', 'product owner', 'head of product'];
return phrases.map(title_only => ({ json: { title_only, page: 1 } }));

// One item per unique Adzuna job, in JobPilot's common job shape.
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  for (const j of item.json.results || []) {
    if (!j.id || seen.has(j.id)) continue;
    seen.add(j.id);
    const salary = j.salary_min && !Number(j.salary_is_predicted)
      ? `£${Math.round(j.salary_min)}–${j.salary_max ? Math.round(j.salary_max) : ''}` : null;
    out.push({ json: {
      id: `adzuna:${j.id}`,
      source: 'adzuna',
      market: 'UK',
      title: (j.title || '').replace(/<[^>]+>/g, '').trim(),
      company: j.company?.display_name || null,
      location: j.location?.display_name || null,
      remote: /remote|hybrid/i.test(`${j.title} ${j.description}`) ? 'mentioned' : 'not mentioned',
      published: (j.created || '').slice(0, 10) || null,
      salary,
      description: (j.description || '').replace(/<[^>]+>/g, '').trim(), // Adzuna gives a snippet only
      description_missing: !j.description,
      link: j.redirect_url,
      external_link: null,
      attribution: 'Adzuna',
    } });
  }
}
return out;

// Keep only titles that look like product roles; the rest never reach Gemini.
// Kept: product manager/owner/lead/head, Produktmanager(in), Produktverantwortliche(r), PO.
// Dropped: titles without 'product'/'produkt', plus clear non-PM product jobs.
const KEEP = /(product|produkt)/i;
const DROP = /(marketing|trainer|training|control|approval|produktion|\bsales\b|vertrieb|designer|konstruk|qualit|praktik|werkstudent|intern\b|azubi|ausbildung)/i;
const kept = $input.all().filter(i => KEEP.test(i.json.title) && !DROP.test(i.json.title));
return kept;

// Skip jobs scored in an earlier run (ids kept for 30 days).
const store = $getWorkflowStaticData('global');
const seen = store.seen || {};
return $input.all().filter(i => !seen[i.json.id]);

// Group jobs into batches; one Gemini request per batch.
const BATCH = 25;
const MAX_DESC = 1500; // characters per job sent to the model
const jobs = $input.all().map(i => i.json);
const out = [];
for (let k = 0; k < jobs.length; k += BATCH) {
  const slice = jobs.slice(k, k + BATCH);
  out.push({ json: {
    batch: out.length + 1,
    jobs: slice,
    // Short ids (1..n) per batch: the model copies these reliably, unlike long source ids.
    modelInput: slice.map((j, idx) => ({ id: String(idx + 1), market: j.market, title: j.title, company: j.company,
      location: j.location, remote: j.remote, salary: j.salary,
      description: (j.description || '').slice(0, MAX_DESC) })),
  } });
}
return out;

// One item per job with score, reason and flags, best first.
const batches = $('Make batches').all();
const store = $getWorkflowStaticData('global');
const seen = store.seen || {};
const today = new Date().toISOString().slice(0, 10);
const out = [];
$input.all().forEach((item, i) => {
  const jobs = batches[i].json.jobs;
  let scores = [];
  try {
    const text = item.json.candidates[0].content.parts[0].text;
    scores = JSON.parse(text).scores || [];
  } catch (e) { /* batch failed: jobs stay unscored */ }
  const byId = Object.fromEntries(scores.map(s => [String(s.id), s]));
  jobs.forEach((job, idx) => {
    const s = byId[String(idx + 1)];
    out.push({ json: { ...job,
      score: s ? Number(s.score) : null,
      reason: s ? s.reason : 'not scored (model error)',
      flags: s ? (s.flags || []) : ['unscored'],
      usage_tokens: item.json.usageMetadata?.totalTokenCount ?? null } });
    if (s) seen[job.id] = today;
  });
});
// forget ids older than 30 days
const cutoff = new Date(Date.now() - 30 * 864e5).toISOString().slice(0, 10);
for (const [id, d] of Object.entries(seen)) if (d < cutoff) delete seen[id];
store.seen = seen;
out.sort((a, b) => (b.json.score ?? -1) - (a.json.score ?? -1));
return out;
